CATEGORY_POS = {"daily-life": "noun", "culture": "noun", "workplace": "noun", "safety": "noun", "laws": "noun"}

def object_particle(ko: str) -> str:
    """Return 을 for a final consonant and 를 for a final vowel."""
    last = next((char for char in reversed(ko.strip()) if "가" <= char <= "힣"), "")
    if not last:
        return "를"
    return "을" if (ord(last) - 0xAC00) % 28 else "를"


def sentence(category: str, ko: str, bn: str, en: str) -> tuple[dict[str, str], str]:
    particle = object_particle(ko)
    if category == "safety":
        return ({"ko": f"{ko}{particle} 확인한 뒤 작업을 시작하세요.", "bn": f"{bn} পরীক্ষা করার পর কাজ শুরু করুন।", "en": f"Check the {en} before starting work."}, "সঠিক উচ্চারণের জন্য Korean বাক্যটি ধীরে পড়ুন।")
    if category == "laws":
        return ({"ko": f"관련 기관에 {ko}{particle} 문의하세요.", "bn": f"সংশ্লিষ্ট প্রতিষ্ঠানে {bn} সম্পর্কে জিজ্ঞাসা করুন।", "en": f"Ask the relevant office about {en}."}, "প্রথমে শব্দটি আলাদা করে, পরে পুরো বাক্যটি বলুন।")
    if category == "workplace":
        return ({"ko": f"작업 전에 {ko}{particle} 확인하세요.", "bn": f"কাজের আগে {bn} পরীক্ষা করুন।", "en": f"Check the {en} before work."}, "কাজের নির্দেশের সাথে শব্দটি একসাথে মনে রাখুন।")
    if category == "culture":
        return ({"ko": f"이번 행사에서 {ko}{particle} 경험해 보세요.", "bn": f"এই অনুষ্ঠানে {bn} অভিজ্ঞতা করে দেখুন।", "en": f"Try experiencing {en} at this event."}, "শব্দটি নতুন Korean সংস্কৃতি প্রসঙ্গে ব্যবহার করুন।")
    return ({"ko": f"필요하면 {ko}{particle} 예약하거나 확인하세요.", "bn": f"প্রয়োজন হলে {bn} বুক করুন বা পরীক্ষা করুন।", "en": f"If necessary, reserve or check {en}."}, "দৈনন্দিন কথোপকথনে শব্দটি ব্যবহার করে বলুন।")


def main() -> None:
    lessons = [json.loads(path.read_text(encoding="utf-8")) for path in sorted(LESSONS.glob("lesson-*.json"))]
    core = {item["ko"].strip() for lesson in lessons for item in lesson.get("vocabulary", [])}
    used = set(core)
    per_category: dict[str, list[dict[str, str]]] = {}
    for category, bank in BANKS.items():
        selected = []
        for ko, romanization, bn, en in bank:
            ko = ko.strip()
            if ko in used:
                continue
            used.add(ko)
            example, tip = sentence(category, ko, bn, en)
            selected.append({"ko": ko, "romanization": romanization, "bn": bn, "en": en, "pos": CATEGORY_POS[category], "example": example, "pronunciationTipBn": tip, "layer": "exam-transfer"})
        per_category[category] = selected

    for lesson in lessons:
        category = lesson["category"]
        needed = 2
        if len(per_category[category]) < needed:
            raise SystemExit(f"not enough unused terms for {category}")
        extras = per_category[category][:needed]
        del per_category[category][:needed]
        for item in extras:
            item["sourceChapter"] = lesson["chapter"]
        lesson["extraVocabulary"] = extras
        lesson["contentVersion"] = "2026-08-23-v5"
        (LESSONS / f"lesson-{lesson['chapter']:02d}.json").write_text(json.dumps(lesson, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    generated = []
    for lesson in lessons:
        generated.append({"chapter": lesson["chapter"], "items": lesson["extraVocabulary"]})
    OUTPUT.write_text(json.dumps(generated, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"seeded {sum(len(entry['items']) for entry in generated)} unique extra terms across 60 lessons")


if __name__ == "__main__":
    main()
